const rateURL = 'https://help.openai.com/en/articles/11481834-chatgpt-rate-card-business-enterpriseedu';
const pricingURL = 'https://learn.chatgpt.com/docs/pricing';
const source = `<p class="caption">Reference checked September 17, 2026 · <a href="${rateURL}" target="_blank" rel="noopener">OpenAI rate card ↗</a></p>`;
const notes = (text, extra = '') => `<h3>For discussion & self-guided learning</h3><p>${text}</p>${extra}`;
const head = (chapter, title, sub = '') => `<p class="eyebrow">${chapter}</p><h2>${title}</h2>${sub ? `<p class="lead">${sub}</p>` : ''}`;
const takeaway = t => `<p class="takeaway">${t}</p>`;
const reveal = (label, body) => `<details class="reveal"><summary>${label}</summary><div>${body}</div></details>`;
const quiz = (id, question, options, feedback) => `<fieldset class="quiz"><legend>${question}</legend><div class="choices">${options.map((o, i) => `<button data-quiz="${id}" data-answer="${i}" aria-pressed="false">${o}</button>`).join('')}</div><div id="${id}" class="feedback" aria-live="polite" data-feedback="${encodeURIComponent(JSON.stringify(feedback))}"></div></fieldset>`;
const demoPending = `<span class="pill">Measured demonstration to be added</span>`;
// Standard Work/Codex credits per million tokens, checked September 24, 2026.
const rateExample = { input: 20000, output: 12000 };
const rateModels = [
    { name: 'GPT-6 Luna', input: 2.5, output: 12.5 },
    { name: 'GPT-6 Sol', input: 50, output: 250 },
    { name: 'GPT-6 Astra', input: 250, output: 1250 }
].map(model => ({ ...model, credits: (rateExample.input * model.input + rateExample.output * model.output) / 1000000 }));
const ecosystemBuilds = {
 broad: { label: 'Broad request · Luna', url: 'demos/ecosystem-broad-luna.html', note: 'Original simulation; page wrapper and base styling added for standalone display.' },
 luna: { label: 'Bounded request · Luna', url: 'demos/ecosystem-bounded-luna.html', note: 'Original standalone output, unchanged.' },
 sol: { label: 'Bounded request · Sol', url: 'demos/ecosystem-bounded-sol.html', note: 'Original standalone output, unchanged.' }
};
const demoCompare = (keys) => `<div class="demo-comparison"><div class="demo-toolbar"><div class="choices" role="group" aria-label="Choose a simulator">${keys.map((key,i)=>`<button data-demo="${key}" aria-pressed="${i===0}">${ecosystemBuilds[key].label}</button>`).join('')}</div><a id="demoFull" href="${ecosystemBuilds[keys[0]].url}" target="_blank" rel="noopener">Open full size</a></div><p id="demoNote" class="caption">${ecosystemBuilds[keys[0]].note}</p><iframe id="demoFrame" class="demo-frame" src="${ecosystemBuilds[keys[0]].url}" title="${ecosystemBuilds[keys[0]].label} ecosystem simulator" sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox" loading="lazy"></iframe><p class="caption">Switching versions restarts the preview. These finished simulations run in your browser without AI calls.</p></div>`;
const ecosystemHandoff = `Build the ecosystem learning activity described in the attached plan. I’ve reviewed and approved the plan; use it as your specification.

Make routine implementation decisions yourself. If the plan is missing something that would change the science or what students learn, ask me before proceeding with that part.

Run the checks in the plan and fix any problems they reveal. When the activity meets the requirements, deliver the finished HTML file and briefly report what you checked and any remaining limitations.`;

const estimateMethod = () => reveal('How these credit estimates were calculated', `<p><strong>Recorded task tokens × September 29 standard Work/Codex rates.</strong> These are estimates at standard speed, not verified deductions from the Clemson credit balance. All three records identify maximum reasoning; a speed tier is not recorded, so standard speed is assumed. Fast mode would multiply these estimates by 2.5.</p><div class="table-scroll"><table class="estimate-table"><thead><tr><th>Build</th><th>Uncached input</th><th>Cached input</th><th>Output</th><th>Est. credits</th></tr></thead><tbody><tr><td>Broad Luna</td><td>103,848</td><td>696,320</td><td>46,866</td><td>1.02</td></tr><tr><td>Bounded Luna</td><td>131,039</td><td>1,913,856</td><td>66,971</td><td>1.64</td></tr><tr><td>Bounded Sol</td><td>47,253</td><td>518,528</td><td>26,882</td><td>11.68</td></tr></tbody></table></div><p>Use the final cumulative usage once. Subtract cached input from total input before applying the uncached rate. Output already includes reasoning; do not add reasoning tokens again. Separately billed tools or unlogged overhead are excluded.</p><p>Luna rates per million: 2.5 input / 0.25 cached / 12.5 output. Sol: 50 / 5 / 250. <a href="${rateURL}" target="_blank" rel="noopener">Current rate card</a>.</p><p class="caption">Luna times supplied by the facilitator: 17m 31s / 24m 41s. Sol time from task start/end: 9m 42s. The bounded Luna log spans 24m 48s; the slide retains the supplied display time. Packaging and workshop integration are not part of these original-build estimates.</p>`);

const boundedPromptHTML = "<div class=\"full-prompt\"><p class=\"caption\">Original bounded prompt used for the ecosystem build. Formatting adjusted for reading; wording preserved.</p><p>Build a polished, interactive ecosystem learning activity for an introductory college audience. The activity should take about two minutes and help learners investigate how removing predators can indirectly affect vegetation.</p><h3><strong>Deliverable</strong></h3><p>Create one downloadable file named <code>ecosystem.html</code>, containing all HTML, CSS, JavaScript, and artwork. It must work in a browser without installation, external libraries, network requests, API keys, or a backend, and be suitable for embedding in another website. Provide the actual file, not just code in a message.</p><h3><strong>Learning experience</strong></h3><ol><li>Open with a visually rich meadow containing vegetation, rabbits, and foxes. Show a short question: \u201cIf the foxes disappear, what happens to the plants?\u201d</li><li>Let learners predict: plants increase, decrease, or stay about the same. Record the choice without immediately judging it.</li><li>Provide \u201cRun baseline\u201d and \u201cRemove foxes &amp; compare\u201d buttons. Both scenarios must start from the same initial conditions, with predator removal as the only difference.</li><li>Animate each scenario over roughly 20 seconds. Show vegetation changing and animals moving, alongside a synchronized graph of vegetation, rabbit, and fox abundance.</li><li>End with a short explanation grounded in the simulated results, inviting learners to compare their prediction with what happened.</li></ol><h3><strong>Visual direction</strong></h3><p>Make the landscape the focal point, occupying at least half the interface. Use layered, original vector or canvas artwork: grasses, terrain, recognizable animal silhouettes, and restrained movement. Aim for the visual quality of an interactive science exhibit.<br>Use a light background with Clemson orange (#F56600) and purple (#522D80) as interface accents. Keep instructions brief and labels readable when projected over Zoom. Avoid emoji artwork, stock photos, decorative dashboards, and excessive text.</p><h3><strong>Model integrity</strong></h3><p>Use a simple, deterministic teaching model: vegetation regrows with a finite carrying capacity; rabbits consume vegetation and depend on it for growth; foxes consume rabbits and depend on them for growth. Keep populations nonnegative and handle extinction without errors.<br>Drive the graph, counts, and landscape from the same simulation state. If animal icons represent multiple individuals, label that clearly.<br>Use identical rules and parameters across both scenarios. Do not script a predetermined animation independently of the model.<br>Include a compact \u201cAbout this model\u201d disclosure with the rules, parameter values, and the statement: \u201cA simplified teaching model, not a forecast of a real ecosystem.\u201d Explain that outcomes depend on assumptions and timescale.</p><h3><strong>Controls and accessibility</strong></h3><p>Include play/pause, reset, and a clearly labeled scenario selector. Reset must restore the initial state and clear the graph. Make controls keyboard-accessible with visible focus. Distinguish graph series with labels or line styles as well as color. Respect reduced-motion preferences and provide a readable numerical summary.</p><h3><strong>Scope and completion</strong></h3><p>Keep this to one screen on a laptop, with a stacked layout on smaller screens. No accounts, scoring system, extra species, weather controls, sound, or additional lessons.<br>Check both scenarios, pause/resume, reset, graph consistency, and layout. Fix failures in these requirements, then stop. Do not add features after the checks pass.<br>Alongside the file, briefly report the checks actually performed and any remaining limitations.</p><p><a href=\"demos/bounded-luna-prompt.txt\" download=\"ecosystem-bounded-prompt.txt\">Download original prompt</a></p></div>";
const slides = [
    { title: 'Managing your credits',
      section: 'Welcome',
      html: `<div class="hero"><div><p class="eyebrow">CLEMSON CHATGPT EDU · 55 MINUTES</p><h1>How to Control Credit Spend<br><em>In Clemson ChatGPT Edu</em></h1><p class="lead">Know what you’re using. Decide where more capability is worth it.</p><div class="meta"><span>Staff · Faculty · Students</span><span>No coding experience needed</span></div></div><div class="hero-art"><span class="tag">TODAY’S QUESTION</span><div class="big">What does<br>this task need?</div><p>A model, a clear scope, and a way to check the result.</p><div class="mini-bars" aria-hidden="true"><span style="height:20%"></span><span style="height:50%"></span><span style="height:100%"></span></div></div></div>`,
      notes: notes('Some useful tasks consume no credits. A single request can also initiate substantial work. We will make predictions, inspect results, and decide what to do next. No coding knowledge is needed. All activities in this draft run locally in your browser; the assistant is a placeholder.', '<p><strong>Facilitator:</strong> 47 minutes of material plus eight minutes of questions. No breakout rooms.</p>')
    },
    { title: 'What you’ll leave with',
      section: 'Welcome',
      html: head('01 / YOUR OUTCOMES', 'Four topics for today') + `<div class="outcomes"><div><span>01</span><h3>Where do I stand?</h3><p>Find and interpret your usage.</p></div><div><span>02</span><h3>Where should I start?</h3><p>Choose a model and reasoning setting.</p></div><div><span>03</span><h3>When should I move up?</h3><p>Bound the task. Check the result. Escalate deliberately.</p></div><div><span>04</span><h3>What if I’m running low?</h3><p>Adjust your approach and find the right support.</p></div></div><div class="method"><b>Predict</b><span>→</span><b>Inspect</b><span>→</span><b>Decide</b></div>`,
      notes: notes('Focus on the finished result and the decisions around it. You do not need to understand how an interactive tool is coded to test whether it works or decide whether it was worth building.')
    },
    { title: 'What is already included?',
      section: 'Included use',
      html: head('02 / MAKE A PREDICTION', 'Useful doesn’t always mean credit-consuming.', 'Which of these uses of ChatGPT Edu consumes credits?') + `<div class="thirds"><div class="card"><img class="tile-screenshot" src="assets/slide-2-explanation.png" alt="ChatGPT explains Simpson’s Paradox in statistics." role="button" tabindex="0" aria-haspopup="dialog" title="Enlarge image"><h3>A clearer explanation</h3><p>Turn a dense concept into something you can work with.</p></div><div class="card"><img class="tile-screenshot" src="assets/slide-2-deep-research-result.png" alt="Deep Research report on how background music may affect concentration while studying." role="button" tabindex="0" aria-haspopup="dialog" title="Enlarge image"><h3>A research briefing</h3><p>Explore a topic with Deep Research and inspect its sources.</p></div><div class="card"><img class="tile-screenshot" src="assets/slide-2-image-generation.png" alt="Generated scientific illustration of microplastics moving through a freshwater food web." role="button" tabindex="0" aria-haspopup="dialog" title="Enlarge image"><h3>A presentation image</h3><p>Create an illustration for a talk or class.</p></div></div>` + quiz('included', 'Choose your prediction', ['Only the explanation', 'All three could', 'None of them'], ['Ordinary chat can be included, and Edu also includes limited Deep Research and image generation. Reveal the allowances below.', 'Yes—depending on the model used and your remaining included feature allowance. Reveal the details below.', 'Some use is included. The model and remaining feature allowance determine whether credits apply.']) + reveal('Reveal the included allowances', `<div class="thirds allowances"><div><b>Instant</b><p>Ordinary responses use no credits; automatic reasoning can incur credits.</p></div><div><b>5</b><p>Deep Research queries</p></div><div><b>3</b><p>Image generations</p></div></div><p>Edu feature allowances apply per rolling 24 hours, not a midnight reset. Check your remaining allowance. These are feature allowances, not a blanket exemption for Work/Codex.</p>${source}`),
      notes: notes('Ask for a prediction before opening the reveal. The important qualifier is “could.” An Instant-selected request may route to a charged reasoning model. Included feature allowances can be exhausted. Confirm Clemson applicability before live delivery.', source)
    },
    { title: 'Read your usage',
      section: 'Monitor',
      html: head('03 / CHECK YOUR POSITION', '400 credits left.<br>What happens next?', 'A balance is useful when you connect it to the work ahead.') + `<div class="grid"><div class="card balance"><span class="tag">FICTIONAL ACCOUNT</span><div class="balance-number">600 <small>/ 1,000 used</small></div><div class="meter"><span></span></div><div class="balance-bottom"><b>400 remaining</b><span>12 days left</span></div><p class="caption">Practice display · not your actual balance</p></div><div><ol class="steps"><li>Confirm the <strong>Clemson workspace</strong>.</li><li>Open <strong>Settings → Usage</strong>.</li><li>Find the limit, usage, and reset information.</li></ol><a class="text-link" href="https://chatgpt.com/#settings/Usage" target="_blank" rel="noopener">Open ChatGPT usage ↗</a><p class="caption">Keep your balance private. Follow the sample if you prefer.</p></div></div>` + quiz('balance', 'Your next week is mostly ordinary chat. What would you do?', ['Stop using ChatGPT', 'Check what upcoming tasks need', 'Spend the rest before reset'], ['The balance alone is not a reason to stop. Look at whether upcoming tasks actually consume credits.', 'A sensible next step. If a large advanced task is coming up instead, scope a small trial and measure it first.', 'There is no need to spend credits simply because they are available. Use them where they help.']) + takeaway('Check before substantial work. Check afterward. Use the difference to plan.'),
      notes: notes('The 1,000-credit allowance is fictional, not Clemson’s current default. The source draft says allowances may change with campuswide usage. Recheck the actual navigation and reset information in the workspace. Reporting may lag; a balance that has not moved immediately does not prove a task was free.')
    },
    { title: 'Know which meter applies',
      section: 'Models & rates',
      html: head('04 / THE BILLING CONTEXT', 'Same model name.<br>Different way of counting.') + `<div class="grid billing-context"><div class="card"><span class="tag">CHAT</span><h3 class="large-label">Per message</h3><figure class="chat-controls-figure"><img class="tile-screenshot chat-controls-image" src="assets/chat-mode-instant.png" alt="ChatGPT with Chat selected at the top and the Instant dropdown at the right of the message box. Select to enlarge." role="button" tabindex="0" aria-haspopup="dialog" title="Enlarge Chat controls"><figcaption><strong>1 · Select Chat</strong> at the top.<br><strong>2 · Open the Instant dropdown</strong> beside the message box to choose Instant or a Thinking level.</figcaption></figure><p>Some Chat options have a fixed credit rate.</p><div class="price-line"><span>Sol Chat</span><b>10 <small>credits / message</small></b></div><p>Medium, High, and Extra High share that rate.</p></div><div class="card purple"><span class="tag">WORK / CODEX</span><h3 class="large-label">Per token</h3><p>Credits depend on what the model processes and produces.</p><div class="token-flow"><span>Inputs</span><span>Reasoning & work</span><span>Outputs</span></div><p>Scope, history, tools, and settings can change consumption.</p></div></div>` + takeaway('Check the mode and current rate—not just the model’s name.') + source,
      notes: notes('Tokens are units of information processed or generated. In token-priced work, more context and processing can increase usage. Avoid the universal rule “higher reasoning always costs more”: fixed-price Chat settings are a counterexample. Model names and availability change. Check the actual Clemson picker and the linked rate card before teaching this page.', source)
    },
    { title: 'Make the rate difference concrete',
      section: 'Models & rates',
      html: head('05 / COMPARE A FIXED WORKLOAD', 'One task, three model rates.', 'Fictional example · GPT-6 in Work / Codex · standard speed') + `<div class="rate-example"><div><span class="tag">YOUR REQUEST · PROGRAM ATTACHED</span><p>“Build a one-day conference planner with topic filters and overlap warnings. Check session names and times against the program.”</p></div><div><span class="tag">SAMPLE RESPONSE · EXCERPT</span><p>“The planner is ready. Select sessions to build your schedule; overlapping choices are flagged.”</p><span class="caption">Deliverable: an interactive page, its code, and checks.</span></div></div><div class="grid rate-grid rate-example-grid"><div><div class="choices model-choices">${rateModels.map((model, i) => `<button data-model="${i}" aria-pressed="${i === 0}">${model.name}</button>`).join('')}</div><div class="cost-number" aria-live="polite"><span id="cost">${rateModels[0].credits.toFixed(2)}</span><small>credits</small></div><p id="costModel">${rateModels[0].name}</p><div class="fixed-input">Assume 20,000 uncached input tokens<br>and 12,000 total billable output tokens.</div></div><div class="rate-chart" aria-label="Illustrative credits: GPT-6 Luna 0.20, GPT-6 Sol 4.00, GPT-6 Astra 20.00">${rateModels.map((model, i) => `<div class="bar-row${i === 0 ? ' selected' : ''}" data-bar="${i}"><div><b>${model.name}</b><span>${model.credits.toFixed(2)}</span></div><div class="bar-track"><span style="width:${model.credits / rateModels[2].credits * 100}%"></span></div></div>`).join('')}</div></div>` + takeaway('For these quantities: Sol costs 20× Luna; Astra costs 100× Luna. Is the added capability needed?') + `<p class="caption">Assumed usage, not a measured run or a claim of equal results. Actual token counts vary; no extra tool charges included. <a href="${rateURL}" target="_blank" rel="noopener">Rate card checked September 24, 2026 ↗</a></p>` + reveal('What about performance? View the benchmark', `<p><strong>OpenAI’s AutomationBench chart</strong> compares score with dollar cost per task. Those dollars are not Clemson ChatGPT Edu credits.</p><figure class="benchmark-figure"><a href="assets/automationbench-gpt6.png" target="_blank" rel="noopener" aria-label="Open full-size AutomationBench chart in a new tab"><img src="assets/automationbench-gpt6.png" alt="OpenAI AutomationBench chart. GPT-6 Luna appears at lower cost and lower scores; Sol occupies the middle; Astra reaches higher scores at higher cost. The horizontal dollar-cost axis is logarithmic. The chart includes earlier GPT models and Claude comparisons."></a><figcaption>Supplied OpenAI chart · AutomationBench 1.0.6 · select the image for full size. Original labels and caveats are preserved.</figcaption></figure><p><strong>Discussion:</strong> What improvement would justify moving up a model for your task?</p><p class="caption">This is one vendor-reported benchmark, not a prediction of performance on your work. Compare your own results and total effort before drawing a conclusion.</p>`),
      notes: notes('The prompt and response are fictional excerpts. Imagine the full job reads an attached program and generates a working planner plus code and checks. We assume 20,000 uncached input tokens and 12,000 total billable output tokens across the task, including reasoning where billed—not just the words in the displayed response. These quantities are chosen for arithmetic, not inferred from the prompt or guaranteed for this task. Holding usage fixed isolates the rate difference; real models can differ in token use, quality, and retries.', `<p>Standard credits per million input / cached input / output tokens: GPT-6 Luna 2.5 / 0.25 / 12.5; GPT-6 Sol 50 / 5 / 250; GPT-6 Astra 250 / 25 / 1,250. No cached input is assumed here.</p><p>Input + output: Luna 0.05 + 0.15 = 0.20; Sol 1.00 + 3.00 = 4.00; Astra 5.00 + 15.00 = 20.00 credits. Fast mode has a 2.5× multiplier; this example uses standard speed. GPT-6 Luna and Sol are Work/Codex models, not Chat options.</p><p><a href="${rateURL}" target="_blank" rel="noopener">Current OpenAI rate card ↗</a></p>`)
    },
    { title: "A short request, a real HPC Day planner", section: "Scope",
      html: head('06 / WHAT DID YOU JUST ASK FOR?', '“Turn this program into an interactive planner.”', 'Try it with Clemson’s actual HPC Day 2026 agenda.') + `<div class="process-strip"><span><b>01</b> Read 11 pages</span><span><b>02</b> Match times & rooms</span><span><b>03</b> Build the planner</span><span><b>04</b> Check conflicts</span></div><div class="demo-toolbar"><p>Select two sessions in the same time slot. Then filter by topic: does your selection stay visible?</p><a href="demos/hpc-day-planner.html" target="_blank" rel="noopener">Open full size</a></div><iframe class="demo-frame agenda-frame" src="demos/hpc-day-planner.html" title="Clemson HPC Day 2026 interactive agenda planner" sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox"></iframe><p class="caption"><a href="assets/HPC-Day-2026-Agenda.pdf" target="_blank" rel="noopener">Source agenda · September 18, 2026</a> · Working example built for this workshop; no measured build-cost claim.</p>` + takeaway('The work behind the prompt matters more than the number of words.'),
      notes: notes("This working planner uses the supplied HPC Day 2026 agenda. Session blocks preserve the printed times and rooms; topic tags are editorial aids. It flags overlapping time intervals, not travel-time feasibility. Individual talks without their own times remain grouped in their printed session. This is a newly built workshop example, not one of the measured simulator runs.")
    },
    { title: "Compare ecosystem build effort", section: "Scope",
      html: head('07 / COMPARE TWO REQUESTS', 'A clearer brief. A longer run.', 'Two ecosystem builds using Luna. Predict which one better serves the lesson.') + `<div class="grid"><div class="card"><span class="tag">BROAD REQUEST · EXACT PROMPT</span><blockquote>Build a visually engaging ecosystem simulation to teach population dynamics.</blockquote><div class="run-metric"><span>Elapsed time</span><strong>17m 31s</strong></div><p class="credit-pending"><strong>≈1.02 credits</strong> · estimated at standard rates</p></div><div class="card orange"><span class="tag">BOUNDED REQUEST · BRIEF SUMMARY</span><blockquote>Teach predator removal with a prediction, two comparable scenarios, an animated meadow, and a graph. Deliver one offline HTML file; check the controls and model, then stop.</blockquote><button id="readBoundedPrompt" class="prompt-open" aria-haspopup="dialog">Read full bounded prompt</button><div class="run-metric"><span>Elapsed time</span><strong>24m 41s</strong></div><p class="credit-pending"><strong>≈1.64 credits</strong> · estimated at standard rates</p></div></div><div class="evidence-band"><strong>7m 10s longer</strong><span>The bounded run took about 41% longer and used about 61% more estimated credits. Was the result more useful?</span></div>` + quiz('scopeCompare','What would you need before calling either one better value?', ['Elapsed time alone', 'Credits and a check of the learning activity', 'The shorter prompt'], ['Elapsed time includes more than billable model work. We also need credit use and a useful result.', 'Yes. Compare credits, educational usefulness, and any repair effort. Inspect the outputs next.', 'Prompt length alone does not tell us the amount or quality of work performed.']) + estimateMethod() + `<p class="caption">Read the original prompts: <a href="demos/broad-luna-prompt.txt" target="_blank" rel="noopener">broad Luna</a> · <a href="demos/bounded-luna-prompt.txt" target="_blank" rel="noopener">bounded Luna</a>.</p>` + takeaway('A boundary defines the job. It does not guarantee a cheaper or faster run.'),
      notes: notes("Elapsed times were supplied by the facilitator: broad Luna 17m 31s; bounded Luna 24m 41s. Credit figures are estimates from recorded cumulative tokens at standard rates, not observed account deductions. The bounded text on this slide is a summary, not a transcript. The briefs differ in educational scope and output requirements; this is a case study, not a controlled estimate of prompting effects. Do not infer credit use from wall-clock time. The finished outputs appear on slide 08.")
    },
    { title: "Inspect the two Luna simulators", section: "Inspect",
      html: head('08 / INSPECT THE RESULT', 'What did the clearer brief buy?', 'Try both Luna builds before deciding which you would use with learners.') + `<div class="inspection-strip"><div><b>Explore</b><span>Broad: run the meadow, then try “Add foxes.”</span></div><div><b>Teach</b><span>Bounded: predict, run baseline, then remove foxes.</span></div><div><b>Check</b><span>Can you explain the change? Does reset work?</span></div></div>` + demoCompare(['broad','luna']) + takeaway('Compare usefulness for the lesson—not just visual polish.') + reveal('How to interpret this comparison', `<p>The broad request asked for population dynamics generally. The bounded request specified a predator-removal lesson. A missing prediction step in the broad build is a difference in scope, not proof that Luna ignored an instruction.</p><p>Check clarity, controls, model disclosure, and consistency between the graph and scene. The simulations may use different equations, units, and timescales; their numerical trajectories are not directly comparable.</p>`),
      notes: notes("Give participants a minute to try each version. Ask what they could teach with it and what still needs review. The broad output has been wrapped for standalone display; its original simulation code is retained. The bounded Luna file is copied unchanged. This checks packaging and user experience, not scientific validation of either teaching model.")
    },
    { title: "Compare bounded Luna and Sol", section: "Escalate",
      html: head('09 / CHOOSE THE REMEDY', 'Would Sol improve what matters?', 'Same bounded brief, two model outputs. Test a specific requirement in both.') + `<div class="inspection-strip"><div><b>Learning sequence</b><span>Predict before running; compare baseline with removal.</span></div><div><b>Consistency</b><span>Do the graph, counts, and scene agree?</span></div><div><b>Recovery</b><span>Pause, reset, and change scenarios. What breaks?</span></div></div>` + demoCompare(['luna','sol']) + `<div class="evidence-row"><span>Luna: <b>24m 41s · ≈1.64 credits</b></span><span>Sol: <b>9m 42s · ≈11.68 credits</b></span></div>` + `<p class="caption">Estimated at standard rates. Sol used about 7.1× the credits in these runs, while finishing sooner.</p>` + estimateMethod() + reveal('Use the result to choose a next step', `<p><strong>Missing information?</strong> Clarify the input first.</p><p><strong>A clear requirement failed?</strong> Identify that failure, try the stronger model, and repeat the same check.</p><p><strong>Both meet your needs?</strong> Additional capability may not be worth the extra credits for this task.</p><p>No winner is assumed. Compare complete job costs, including corrections, using the recorded usage estimates and any later repair costs.</p>`) + takeaway('Escalate for a named improvement you can verify.'),
      notes: notes("The facilitator identifies these as the bounded Luna and Sol runs. Original standalone files are unchanged. Do not claim a demonstrated Luna failure or Sol success without observing a specific check. One pair of runs does not establish a universal model ranking. Compare educational behavior, not identical ecological trajectories: implementations can differ even under the same brief.")
    },
    { title: "Make a concrete plan and execution handoff", section: "Combine",
      html: head('10 / DIVIDE THE WORK', 'Hand over a plan someone can execute.', 'For the ecosystem: resolve the model first, then build from approved decisions.') + `<div class="workflow"><div><span class="tag">1 · PLAN WITH SOL / ASTRA</span><h3>Ask for decisions</h3><p>“Propose a thorough plan for how to implement the simulation, including the equations, parameters, starting conditions, and checks. Do not build yet.”</p></div><div><span class="tag">2 · REVIEW YOURSELF</span><h3>Approve the model</h3><p>Check the science and learning objective. Resolve open questions before implementation.</p></div><div><span class="tag">3 · EXECUTE WITH LUNA</span><h3>Provide the brief</h3><p>In a new task, attach the approved plan and source files. Select Luna and request the build.</p></div><div><span class="tag">4 · VERIFY THE RESULT</span><h3>Repeat the checks</h3><p>Test both scenarios and reset. Return a specific failure for correction or escalation.</p></div></div>` + reveal('Example: what to send to Luna', `<p>Attach the approved plan. The message below refers to that plan.</p><pre>${ecosystemHandoff}</pre><button id="copyHandoff">Copy this handoff</button><span id="copyStatus" class="caption" role="status"></span>`) + takeaway('The handoff is the approved decisions + necessary files + explicit checks.') + `<p class="caption">Count planning, execution, and repairs together. For a small task, a separate planning run may cost more than it saves.</p>`,
      notes: notes("This is a proposed workflow, not a fourth measured simulator build. Starting a new task with the approved plan avoids depending on hidden conversation context. Keeping the same task and switching models can also work, but carries the existing history. Choose the actual model in the picker; asking a model to act like another does not switch it. A stronger planning model still requires human review of the science.")
    },
    { title: "Choose who handles each ecosystem step", section: "Combine",
      html: head('11 / YOUR CHOICE', 'Who should handle this part?', 'Allocate three parts of the ecosystem project. Choose a starting approach, then explain it.') + `<div class="assignment"><label><span><b>Resolve unstable population behavior</b><small>The equations produce runaway values. Work out whether the rules or numerical method need revision.</small></span><select id="stage0"><option value="">Choose…</option><option>Luna</option><option>Sol / Astra</option><option>Human decision</option></select></label><label><span><b>Build controls from an approved specification</b><small>Add play/pause and reset, using the supplied state and acceptance checks.</small></span><select id="stage1"><option value="">Choose…</option><option>Luna</option><option>Sol / Astra</option><option>Human decision</option></select></label><label><span><b>Approve what the lesson teaches</b><small>Decide whether the simplifications and explanation are appropriate for your students.</small></span><select id="stage2"><option value="">Choose…</option><option>Luna</option><option>Sol / Astra</option><option>Human decision</option></select></label></div><button class="action" id="checkStages">Discuss these choices</button><div id="stagesFeedback" class="feedback" aria-live="polite"></div>`,
      notes: notes("Suggested starting split: a stronger model can help diagnose interacting mathematical constraints; Luna is a reasonable trial for implementing specified controls; the instructor owns pedagogical and scientific approval. These are starting choices, not claims that only one model can do each task.")
    },
    { title: 'Plan one task of your own',
      section: 'Apply',
      html: head('12 / MAKE IT YOURS', 'What would you like to build or understand?', 'Pick a task you care about. Write a few sentences about how you’ll start and how you’ll judge the result. This is a plan for you; nothing is sent to a model.') + `<div class="grid"><div><label for="scenario" class="field-label">Choose a starting point</label><select id="scenario"><option>Research data explorer</option><option>Visual study simulator</option><option>Personal conference planner</option><option>Proposal comparison</option><option>My own task</option></select><label for="taskPlan" class="field-label">Your plan</label><textarea id="taskPlan" rows="5" placeholder="I want to…&#10;I’ll start with… and give it…&#10;I’ll ask for this first…&#10;I’ll know it works when…&#10;If it doesn’t work, I’ll…&#10;Before asking for more, I’ll check…"></textarea><button id="downloadPlan">Save my plan</button><span id="planStatus" class="caption" role="status"></span></div><div class="card assistant-card"><span class="tag">WORKSHOP ASSISTANT</span><div class="assistant-mark" aria-hidden="true">?</div><h3>Personalized guidance,<br>coming later.</h3><p>The assistant will help scope your task, suggest a starting model, and identify checks and escalation triggers.</p><span class="pill">Placeholder · no API connected</span></div></div>` + reveal('Example: my plan for the ecosystem activity', `<p class="caption">Use this as a guide for your own notes. You do not need a detailed technical plan yet.</p><ol class="example-plan"><li><strong>What I want:</strong> I want students to predict what happens to plants when foxes disappear, then explore a simulation to see whether their prediction holds.</li><li><strong>How I’ll start:</strong> I’ll try Luna. I’ll give it the learning goal and a description of how the ecosystem should behave that I’ve checked for accuracy.</li><li><strong>What I’ll ask for first:</strong> One working activity with two experiments—foxes present and foxes removed—a population graph, and a reset button. I’ll leave extra species and weather controls for later.</li><li><strong>How I’ll check it:</strong> I’ll run both experiments and check that only the foxes change at the start. I’ll also check that the graph agrees with the displayed populations and that reset takes me back to the beginning.</li><li><strong>What I’ll do if it fails:</strong> I’ll describe the problem and ask Luna to fix it. If it still cannot follow the ecosystem rules I supplied, I’ll give Sol the same instructions and the specific failed check.</li><li><strong>Before expanding it:</strong> I’ll review the credit use and the time I spent checking and correcting the activity. Then I’ll decide whether more features are worth adding.</li></ol><p>For your task, name the first useful result, how you’ll check it, and what would make you change your approach.</p>`),
      notes: notes('The text remains in the current browser session; Save downloads a plain-text plan. The future assistant can ask a few clarifying questions and give feedback. Until then, use the worked example and facilitator discussion. Keep sensitive data out of workshop examples.')
    },
    { title: 'When the balance is running low',
      section: 'Continue',
      html: head('13 / YOUR NEXT STEP', 'Running low doesn’t mean guessing.') + `<div class="thirds"><div class="card"><span class="number">01</span><h3>Check</h3><p>Confirm remaining credits, reset information, and what your next task needs.</p><a href="https://chatgpt.com/#settings/Usage" target="_blank" rel="noopener">Open usage ↗</a></div><div class="card"><span class="number">02</span><h3>Adjust</h3><p>For an explanation, check whether an included Chat option is sufficient. For a build, test one small feature with Luna before requesting the whole application. Recheck usage before expanding.</p></div><div class="card"><span class="number">03</span><h3>Ask</h3><p>Faculty and staff: request a higher credit tier for sustained University needs.</p></div></div>` + quiz('cap', 'Does “keep this under 10 credits” enforce a spending cap?', ['Yes', 'No—this is guidance'], ['A prompt is advisory. Use actual settings and usage controls; do not treat the wording as an enforced cap.', 'Correct. Prompt wording can guide scope, but it is not an enforced credit cap.']) + takeaway('A higher allowance changes the budget. It does not itself add models or features.'),
      notes: notes('Clemson-specific statements come from the organizer’s draft, not a live workspace check. Confirm reset behavior, student support, and what remains available after a limit. Notifications and enforced controls are different.', `<p><a href="https://www.clemson.edu/ai/guidelines/" target="_blank" rel="noopener">Clemson AI guidelines ↗</a> · <a href="https://clemson.service-now.com/csm?id=sc_cat_item&sys_id=2bae9ec1935ffe10ccdc3ce86cba10bc&sysparm_category=983d1e81935ffe10ccdc3ce86cba1090" target="_blank" rel="noopener">Higher-tier request from source draft ↗</a></p>`)
    },
    { title: 'The guidelines to keep',
      section: 'Remember',
      html: head('14 / TAKE THIS WITH YOU', 'Use credits where they help.') + `<div class="summary-grid"><ol class="summary-list"><li><b>Check your position.</b><span>Workspace, allowance, usage, reset.</span></li><li><b>Use what is included.</b><span>Match the feature to the task.</span></li><li><b>Check current choices.</b><span>Model, mode, and applicable rate.</span></li><li><b>Bound the work.</b><span>Sources, outputs, checks, stopping point.</span></li></ol><ol class="summary-list" start="5"><li><b>Inspect before spending more.</b><span>Name what failed.</span></li><li><b>Escalate deliberately.</b><span>Use explicit handoffs when mixing models.</span></li><li><b>Compare the whole job.</b><span>Credits, retries, and remaining human work.</span></li></ol></div>`,
      notes: notes('What is one habit you will use on your next task? The aim is neither minimum spending at all costs nor automatic use of the strongest model. It is a useful result with an informed choice about resources.')
    },
    { title: "Apply the workflow to a new lesson", section: "Exit check & questions",
      html: head('15 / ONE LAST DECISION', 'The ecosystem worked. Now build ten lessons?', 'You want ten interactive biology activities for a course. Each needs a prediction, a visual experiment, and useful feedback.') + `<div class="grid"><div>` + quiz('exit', 'What is a sensible next step before building all ten?', ['Ask the strongest model to build all ten', 'Pilot one new lesson with explicit checks', 'Reuse the ecosystem code without review'], ['That may be justified by prior evidence, but this ecosystem example does not establish the cost or difficulty of all ten topics.', 'Yes. Choose one representative new topic, approve its teaching model, and measure the effort to get a usable lesson.', 'Some interface code may be reusable. The science, interactions, and feedback still need topic-specific review.']) + reveal('What the one-lesson pilot would establish', `<p><strong>Example topic:</strong> a visual activity on how competition for a limited resource affects two populations.</p><p><strong>Start:</strong> provide approved model rules and a bounded brief; try Luna if the implementation is straightforward.</p><p><strong>Check:</strong> resource changes affect the simulation according to those rules; feedback explains the observed result; reset works.</p><p><strong>Measure:</strong> credits for the build and repairs, elapsed time, and instructor review effort.</p><p><strong>Decide:</strong> reuse the approach, improve the brief, or try Sol on a specific failed check. Use the pilot to estimate a range for the remaining lessons—not an exact tenfold budget.</p>`) + `</div><div class="closing"><span class="tag">DISCUSS & ASK QUESTIONS</span><h3>What evidence would make you scale up?</h3><p>A usable lesson.<br>A checked teaching model.<br>A measured cost.</p><button data-go="14">Return to the guidelines</button></div></div>`,
      notes: notes("This is a transfer question: participants apply the same scope/check/measure/escalate process to a new teaching task. It is not a proposal-scoring exercise. Do not assume the cost of one ecosystem build predicts all topics. Discuss which parts can be reused and which need fresh scientific review.")
    },

];
let current = 0; const snapshots = new Map(); const $ = id => document.getElementById(id);
function saveState() { snapshots.set(current, $('slide').innerHTML); }
function go(n) { if (n < 0 || n >= slides.length) return; saveState(); current = n; location.hash = String(n + 1); render(); $('slide').focus({ preventScroll: true }); window.scrollTo(0, 0) }
function render() { const s = slides[current]; $('slide').innerHTML = snapshots.get(current) || s.html; $('sectionName').textContent = s.section; $('count').textContent = `${String(current + 1).padStart(2, '0')} / ${slides.length}`; $('progress').style.width = `${(current + 1) / slides.length * 100}%`; $('notes').innerHTML = s.notes; $('prev').disabled = current === 0; $('next').disabled = current === slides.length - 1; $('next').innerHTML = current === slides.length - 1 ? 'End' : 'Next <span aria-hidden="true">→</span>'; document.title = `${current + 1}. ${s.title} · Clemson credit workshop`; wire(); }
function modal(title, body) { $('modalTitle').textContent = title; $('modalBody').innerHTML = body; $('modal').showModal(); $('modalBody').querySelectorAll('[data-go]').forEach(b => b.onclick = () => { $('modal').close(); go(Number(b.dataset.go)) }) }
$('contents').onclick = () => modal('Workshop contents', `<div class="toc">${slides.map((s, i) => `<button data-go="${i}" ${i === current ? 'aria-current="page"' : ''}><span>${String(i + 1).padStart(2, '0')}</span>${s.title}</button>`).join('')}</div>`);
$('assistant').onclick = () => modal('Workshop assistant', '<span class="pill">Placeholder · no API connected</span><p>This space will offer help with the current activity, explain model choices, and guide you through the workshop on your own.</p><p>For now, use the worked examples and Notes & sources on each slide.</p>');
$('closeModal').onclick = () => $('modal').close(); $('modal').addEventListener('click', e => { if (e.target === $('modal')) { const r = $('modal').getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) $('modal').close() } });
$('prev').onclick = () => go(current - 1); $('next').onclick = () => go(current + 1); $('notesButton').onclick = () => { const n = $('notes'); n.hidden = !n.hidden; $('notesButton').setAttribute('aria-expanded', String(!n.hidden)); if (!n.hidden) n.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) };
window.addEventListener('keydown', e => { if ($('modal').open || /INPUT|TEXTAREA|SELECT|BUTTON|SUMMARY/.test(e.target.tagName) || e.ctrlKey || e.altKey || e.metaKey) return; if (e.key === 'ArrowRight') { e.preventDefault(); go(current + 1) } if (e.key === 'ArrowLeft') { e.preventDefault(); go(current - 1) } });
window.addEventListener('hashchange', () => { const n = Number(location.hash.slice(1)) - 1; if (Number.isInteger(n) && n >= 0 && n < slides.length && n !== current) { saveState(); current = n; render() } });
function wire() {
    if ($('readBoundedPrompt')) $('readBoundedPrompt').onclick = () => { modal('The full bounded prompt', boundedPromptHTML); $('modal').scrollTop = 0; };
    document.querySelectorAll('[data-demo]').forEach(button => button.onclick = () => {
        const build = ecosystemBuilds[button.dataset.demo];
        document.querySelectorAll('[data-demo]').forEach(b => b.setAttribute('aria-pressed', String(b === button)));
        $('demoFrame').src = build.url; $('demoFrame').title = build.label + ' ecosystem simulator';
        $('demoFull').href = build.url; $('demoNote').textContent = build.note;
    });
    document.querySelectorAll('.tile-screenshot').forEach(img => {
        const openPreview = () => {
            const title = img.classList.contains('chat-controls-image') ? 'Chat mode and the Instant / Thinking selector' : img.closest('.card')?.querySelector('h3')?.textContent || 'Image preview';
            modal(title, `<img class="lightbox-image" src="${img.src}" alt="${img.alt}">`);
        };
        img.onclick = openPreview;
        img.onkeydown = e => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                openPreview();
            }
        };
    });
    document.querySelectorAll('[data-quiz]').forEach(b => b.onclick = () => { const group = b.dataset.quiz; document.querySelectorAll(`[data-quiz="${group}"]`).forEach(x => x.setAttribute('aria-pressed', String(x === b))); const f = $(group); f.textContent = JSON.parse(decodeURIComponent(f.dataset.feedback))[Number(b.dataset.answer)] });
    document.querySelectorAll('[data-model]').forEach(b => b.onclick = () => { const i = Number(b.dataset.model); document.querySelectorAll('[data-model]').forEach(x => x.setAttribute('aria-pressed', String(x === b))); $('cost').textContent = rateModels[i].credits.toFixed(2); $('costModel').textContent = rateModels[i].name; document.querySelectorAll('[data-bar]').forEach(x => x.classList.toggle('selected', Number(x.dataset.bar) === i)) });
    document.querySelectorAll('[data-scope]').forEach(b => b.onclick = () => { b.setAttribute('aria-pressed', String(b.getAttribute('aria-pressed') !== 'true')); const chosen = [...document.querySelectorAll('[data-scope][aria-pressed="true"]')].map(x => x.dataset.scope); $('scopeResult').textContent = chosen.includes('extras') ? 'Optional extras expand the job. Specify what is required before adding more.' : chosen.length === 3 ? 'A clear source, explicit checks, and a stopping point give the work useful boundaries.' : chosen.length ? 'Good start. Include the source, checks, and a stopping point.' : 'Choose the boundaries you would add.' });
    if ($('checkStages')) $('checkStages').onclick = () => { const values = [0, 1, 2].map(i => $('stage' + i).value); $('stagesFeedback').textContent = values.some(v => !v) ? 'Choose an approach for each stage first.' : 'A reasonable starting split: Sol/Astra to investigate unstable model behavior; Luna to implement approved controls; you to approve the lesson. Treat these as starting choices and judge the result. Scientific review remains necessary.' };
    if ($('copyHandoff')) $('copyHandoff').onclick = async () => { const t = ecosystemHandoff; try { await navigator.clipboard.writeText(t); $('copyStatus').textContent = ' Copied.' } catch { modal('Handoff template', `<pre>${t}</pre>`) } };
    if ($('taskPlan')) $('taskPlan').oninput = e => { e.target.textContent = e.target.value };
    document.querySelectorAll('select').forEach(s => s.onchange = () => { [...s.options].forEach(o => o.toggleAttribute('selected', o.selected)) });
    if ($('downloadPlan')) $('downloadPlan').onclick = () => { const text = $('taskPlan').value.trim(); if (!text) { $('planStatus').textContent = ' Write a few notes first.'; return } const blob = new Blob([`My ChatGPT task plan\n${$('scenario').value}\n\n${text}\n\nCheck usage before and after the trial.\n`], { type: 'text/plain;charset=utf-8' }); const url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = 'my-chatgpt-task-plan.txt'; a.click(); URL.revokeObjectURL(url); $('planStatus').textContent = ' Plan saved.' };
    document.querySelectorAll('[data-go]').forEach(b => b.onclick = () => go(Number(b.dataset.go)));
}
const initial = Number(location.hash.slice(1)) - 1; if (Number.isInteger(initial) && initial >= 0 && initial < slides.length) current = initial; render();
